def _checked(sql, pin):
    if type(sql) is not str or sql.count("$$") != 2:
        raise ValueError("native_zero_fok55_function_identity")
    if hashlib.sha256(sql.split("$$")[1].encode("utf-8")).hexdigest() != pin:
        raise ValueError("native_zero_fok55_function_identity")
    return sql


def statements():
    return (_checked(CURRENT_SQL, CURRENT_BODY_SHA256),)


def restore_statements():
    return (_checked(ORIGINAL_SQL, ORIGINAL_BODY_SHA256),)
